function fib(n){
  n = BigInt(n);
  if(n < 0n) return null;
  function f(k){
    if(k === 0n) return [0n, 1n];
    var a = f(k >> 1n), c = a[0], d = a[1];
    var c2 = c * (2n*d - c);
    var d2 = c*c + d*d;
    return (k % 2n === 0n) ? [c2, d2] : [d2, c2 + d2];
  }
  return f(n)[0];
}
function fibSequence(n){
  n = BigInt(n); var out = [];
  for(var i = 0n; i <= n; i++) out.push(fib(i));
  return out;
}
var EXPORTS = { fib:fib, fibSequence:fibSequence };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FibonacciForgePure = EXPORTS; }
